#include "stdafx.h"#include "HcdElementBase.h"struct SASYS_P{#include "PrivateVars/ASYS.h"};class KASYS : public KHcdElementBase  , protected SASYS_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _ASYS("ASYS", KASYS::Create);IHcdElement *KASYS::Create(){  return new KASYS;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KASYS, 15 )void KASYS::InitParm(){#include "PrivateVars/ASYS.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KASYS::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KASYS::StepCalc( SStepCalcParams &params ){  CYCTIME = params.dtS;  CYCMINS = params.dtS / 60.f;}